const m = $('Telegram Trigger').item.json.message || $('Telegram Trigger').item.json.callback_query.message;
const cid = m.chat.id;
let txt = m.text || m.caption || '';
const prods = $items('Cargar inventario');
const lineas = prods.map(p => { const j = p.json || p;
  return 'ID ' + j.id + ' | ' + j.nombre + ' | stock:' + j.stock + ' | precio:' + j.precio + ' | ' + (j.activo ? 'publicado' : 'oculto'); });
const inv = lineas.join('\n');
return [{ json: { chatId: cid, sessionId: cid, mensaje: txt, inventario: inv } }];

let out = $input.first().json.output || $input.first().json.text || '';
out = String(out).trim();
out = out.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '').trim();
const ini = out.indexOf('{');
const fin = out.lastIndexOf('}');
let d = null;
if (ini >= 0 && fin > ini) {
  try { d = JSON.parse(out.slice(ini, fin + 1)); } catch (e) { d = null; }
}
if (!d) {
  d = { accion: 'consultar', respuesta: out };
}
return [{ json: { accion: d.accion || 'consultar', id: d.id, valor: d.valor, datos: d.datos || {}, respuesta: d.respuesta || '', chatId: $('Preparar entrada').item.json.chatId } }];

const d = $input.first().json;
const acc = d.accion;
const id = d.id;
const valor = d.valor;
const datos = d.datos || {};
const H = { 'Content-Type': 'application/json', 'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJyb2xlIjoiYWRtaW4iLCJpZCI6MSwiaWF0IjoxNzg3NjE5ODk5LCJleHAiOjIxMDI5Nzk4OTl9.EOwKkZgszm1F8x5Z3bV9fKyiNQLe6NVTyX1e9ck1l4s' };
const API = 'https://seiva.com.py/api/productos';

// Acciones que solo responden (no tocan el backend)
if (acc === 'consultar' || acc === 'aclarar' || acc === 'error') {
  return [{ json: { chatId: d.chatId, texto: d.respuesta } }];
}

let url = '', method = 'GET', body = null;
if (acc === 'ajustar_stock') { url = API + '/' + id; method = 'PUT'; body = { stock: Number(valor) }; }
else if (acc === 'editar') { url = API + '/' + id; method = 'PUT'; body = datos; }
else if (acc === 'publicar' || acc === 'despublicar') { url = API + '/' + id + '/toggle'; method = 'PATCH'; }
else if (acc === 'crear') { url = API; method = 'POST'; body = datos; }
else { return [{ json: { chatId: d.chatId, texto: d.respuesta || 'No entendi la accion.' } }]; }

let ok = false, detalle = '';
try {
  const opts = { method: method, url: url, headers: H };
  if (body) opts.body = body;
  const r = await this.helpers.httpRequest(opts);
  ok = true;
  detalle = typeof r === 'string' ? r : JSON.stringify(r);
} catch (e) { ok = false; detalle = 'ERROR: ' + e.message; }

let msg = '';
if (ok) {
  if (acc === 'ajustar_stock') msg = 'Stock actualizado correctamente.';
  else if (acc === 'editar') msg = 'Producto editado correctamente.';
  else if (acc === 'publicar' || acc === 'despublicar') msg = 'Estado actualizado correctamente.';
  else if (acc === 'crear') msg = 'Producto creado correctamente.';
} else {
  msg = 'No pude completar la accion. ' + detalle;
}
return [{ json: { chatId: d.chatId, texto: msg } }];

